import math

BUDGET = 10**8      # rough steps per time limit; lower in Python

def rows(n):
    return [("O(n)", n), ("O(n log n)", n * math.log2(n)), ("O(n^2)", n * n)]

for n in [1_000, 100_000, 1_000_000]:
    print(f"n = {n:,}")
    for name, steps in rows(n):
        verdict = "fits" if steps <= BUDGET else "too slow"
        print(f"  {name:11}{steps:>18,.0f}  {verdict}")

