def is_sorted(nums):
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            return False
        return True

tests = [
    ([1, 2, 3], True),
    ([3, 1, 2], False),
    ([1, 3, 2], False),
    ([], True),
    ([7], True),
    ([2, 2, 2], True),
]
passed = 0
for nums, expected in tests:
    got = is_sorted(nums)
    if got == expected:
        passed += 1
    else:
        print("WRONG:", nums, "expected", expected, "got", got)
print(passed, "of", len(tests), "tests pass")

